await sqs.send(new Sqs.SendMessageCommand({ QueueUrl: queueUrl, MessageBody: JSON.stringify({ Records: [{ eventSource: 'aws:s3', awsRegion: region, eventName: 'ObjectCreated:Put', s3: { bucket: { name: 'source-recovery', arn: 'arn:aws:s3:::source-recovery' }, object: { key: 'events.json', eTag: object.etag, size: object.size } } }] }) }));
const manager = sim.opensearch.serverless.streams as any, host = manager.host, write = host.write.bind(host), acknowledge = manager.ports.acknowledge.bind(manager.ports);
let documentId: string | undefined;
host.write = async (...args: any[]) => { documentId ??= args[3]; if (boundary === 'after-queue-delete') return write(...args); if (boundary === 'after-sink') await write(...args); process.send?.({ boundary, collectionId: id, documentId }); await new Promise(() => {}); };
manager.ports.acknowledge = async (...args: any[]) => { await acknowledge(...args); if (boundary === 'after-queue-delete') { process.send?.({ boundary, collectionId: id, documentId }); await new Promise(() => {}); } };
await aoss.send(new Aoss.CreateIngestionStreamCommand({ collectionId: id, ingestionStreamName: 'source-recovery', indexName: 'records', roleArn: role, source: { s3: { sqsArn: queueArn } } }));
setInterval(() => {}, 1000);
